class AmazingString {

	public static void main(String[] args) {
		String A = "";
		
		int l = 0;
		int r = 0;
		int count = 0;
		int mod = 10003;
		int n = A.length();

		
		while(  r < A.length() ) {
			
			switch(Character.toLowerCase(A.charAt(r))) {
				case 'a' : 
				case 'e' :
				case 'i' : 
				case 'o' : 
				case 'u' : {
					// count = (count + ( A.length() - r) ) % 10003;
					count = (count + (n - r)) % mod;
					break;
				}
				default: {
					// l++;
				}
	
			}
			
			r++;
		}



		System.out.println(count);
	
	}
}